{"content": "import re, json

txt = open("/Users/wushuo/Desktop/环境学院论文/固定燃烧源清单经验缺失处置实验/实验结果/04_实验C_规模与资源表现/100%规模/02_火电热力/03_通用工具调用型Agent/R2/_work/pdf_fulltext.txt", encoding="utf-8").read()
parts = re.split(r"===== PAGE (\d+) =====", txt)
pagemap = {}
for i in range(1, len(parts), 2):
    pagemap[int(parts[i])] = parts[i+1]

def lines_of(page):
    return [l.strip() for l in pagemap[page].split("\n")]

# ---------- Table A.1 pages 32,33 ----------
def parse_a1():
    rows = []
    for page in (32, 33):
        ls = lines_of(page)
        start = None
        for i, l in enumerate(ls):
            if l == "PM2.5-10 a" and i+2 < len(ls) and ls[i+1] == "BC" and ls[i+2] == "OC":
                start = i + 3
                break
        if start is None:
            print("A1 header not found page", page)
            continue
        i = start
        while i < len(ls):
            l = ls[i]
            if l == "" or l.startswith("T/CSES") or l == "全国团体标准信息平台" or re.match(r"^\d+$", l):
                i += 1
                continue
            if i + 6 < len(ls):
                name = ls[i]
                vals = ls[i+1:i+8]
                if len(vals) == 7 and all(re.match(r"^[\d.]+$", v) for v in vals):
                    rows.append({"measure": name, "SO2": vals[0], "NOx": vals[1], "VOCs": vals[2],
                                 "PM2.5": vals[3], "PM2.5_10": vals[4], "BC": vals[5], "OC": vals[6]})
                    i += 8
                    continue
            i += 1
    return rows

a1 = parse_a1()
print("A.1 parsed rows:", len(a1))
for r in a1:
    print(r["measure"], "|", r["SO2"], r["NOx"], r["VOCs"], r["PM2.5"], r["PM2.5_10"], r["BC"], r["OC"])

# ---------- C.1 pages 39, C.2 page 40, C.3 page 41 ----------
def parse_c(headers, page, ncols):
    """headers: list of column header names; returns rows of ncols"""
    ls = lines_of(page)
    start = None
    for i, l in enumerate(ls):
        if l == headers[-1]:
            # ensure it's the last header in sequence
            ok = True
            for j, h in enumerate(headers):
                if i - (len(headers)-1) + j < 0 or ls[i - (len(headers)-1) + j] != h:
                    ok = False
                    break
            if ok:
                start = i + 1
                break
    if start is None:
        print("header not found", headers)
        return []
    rows = []
    i = start
    while i < len(ls):
        l = ls[i]
        if l.startswith("注：") or l == "" or l.startswith("T/CSES") or l == "全国团体标准信息平台" or re.match(r"^\d+$", l):
            i += 1
            continue
        # records: 3 label lines + (ncols-3) value lines
        if i + ncols - 1 < len(ls):
            sec = ls[i]
            if sec in ("电力热力源","工业源","生活源","电力生产","电力供应","热力生产和供应","采矿业、制造业、燃气生产和供应业","民用化石燃料燃烧"):
                rec = [sec]
                vals_ok = True
                for k in range(1, ncols):
                    v = ls[i+k]
                    if k >= 3 and not re.match(r"^[\d.]+$", v):
                        vals_ok = False
                        break
                    rec.append(v)
                if vals_ok:
                    rows.append(rec)
                    i += ncols
                    continue
        i += 1
    return rows

c1 = parse_c(["排放源","部门/行业","燃烧技术","硫分进入底灰比例","灰分进入底灰比例"], 39, 5)
print("\nC.1 rows:", len(c1))
for r in c1: print(r)
c2 = parse_c(["排放源","部门/行业","燃烧技术","烟气中PM2.5占总颗粒物比例","烟气中PM10占总颗粒物比例"], 40, 5)
print("\nC.2 rows:", len(c2))
for r in c2: print(r)
c3 = parse_c(["排放源","部门/行业","燃烧技术","BC占PM2.5比例","OC占PM2.5比例"], 41, 5)
print("\nC.3 rows:", len(c3))
for r in c3: print(r)

json.dump({"A1": a1, "C1": c1, "C2": c2, "C3": c3},
          open("/Users/wushuo/Desktop/环境学院论文/固定燃烧源清单经验缺失处置实验/实验结果/04_实验C_规模与资源表现/100%规模/02_火电热力/03_通用工具调用型Agent/R2/_work/params_std.json", "w"), ensure_ascii=False, indent=1)
