{"content": "# -*- coding: utf-8 -*-
"""
Fixed-combustion POWER (电力热力) inventory computation — generic tool agent run.
Run C-100-POW-GEN-R2. Method: T/CSES 144-2024 城市大气污染源排放清单编制技术指南.
Rules are derived ONLY from the run package inputs (B102-2002, B101-2001, B101-2002,
source_identity_index.json, run_manifest.json) and the provided PDF standard.
"""
import json
import math
import os
import sys

RUN = "/Users/wushuo/Desktop/环境学院论文/固定燃烧源清单经验缺失处置实验/实验结果/04_实验C_规模与资源表现/100%规模/02_火电热力/03_通用工具调用型Agent/R2"
INP = RUN + "/inputs"
OUT = RUN + "/outputs"
WORK = RUN + "/_work"

import pandas as pd
import numpy as np

# ---------------------------------------------------------------- inputs
manifest = json.load(open(RUN + "/run_manifest.json", encoding="utf-8"))
TARGET = manifest["target"]                       # POWER
candidate_ids = manifest["candidate_ids"]

idx = json.load(open(INP + "/source_identity_index.json", encoding="utf-8"))
id_records = idx["records"]
assert len(id_records) == len(candidate_ids)
idmap = {}                                        # source_id -> pandas row index
for rec in id_records:
    row_idx = int(rec["source_row"]) - 1          # header is row 1 in the sheet
    idmap[rec["source_id"]] = row_idx
assert set(idmap.keys()) == set(candidate_ids)

b102 = pd.read_excel(INP + "/基102-2002_原始结构脱敏输入.xlsx", sheet_name="Sheet1", header=0)
assert len(b102) == 5922
b101 = pd.read_excel(INP + "/基101-2002_原始结构脱敏输入.xlsx", sheet_name="Sheet1", header=0)

std = json.load(open(WORK + "/standard_parameters.json", encoding="utf-8"))
D1 = std["D1"]; A1 = std["A1"]; C1 = std["C1"]; C2 = std["C2"]; C3 = std["C3"]

# ---------------------------------------------------------------- constants
D44_POWER = {"4411", "4412", "4417", "4419", "4430", "4420"}
POLLUTANTS = ["SO2", "NOx", "CO", "VOC", "PM2.5", "BC", "OC", "NH3", "PM10"]

FUEL_MAP = {
    "原煤": "煤炭", "无烟煤": "煤炭", "一般烟煤": "煤炭", "褐煤": "煤炭",
    "其他洗煤": "煤炭", "煤制品": "煤炭",
    "焦炭": "焦炭", "煤矸石（用于燃料）": "煤矸石", "其他焦化产品": "其它焦化产品",
    "焦炉煤气": "焦炉煤气", "高炉煤气": "高炉煤气", "转炉煤气": "转炉煤气",
    "发生炉煤气": "其它煤气", "天然气": "天然气", "液化天然气": "液化天然气",
    "液化石油气": "液化石油气", "炼厂干气": "炼厂干气", "原油": "原油",
    "柴油": "柴油", "燃料油": "燃料油", "润滑油": "其它液体燃料",
    "其他石油制品": "其它石油制品", "石油焦": "石油焦",
}
NO_FACTOR_FUELS = {"生物燃料", "城市生活垃圾（用于燃料）", "工业废料（用于燃料）", "其他燃料"}
GAS_M3_FUELS = {"焦炉煤气", "高炉煤气", "其它煤气", "天然气", "转炉煤气", "其它气体燃料"}
COAL_FAMILY = {"煤炭", "焦炭", "煤矸石", "其它焦化产品"}
SOLID_TECH_CODES = {"RM05", "RM04", "RM01", "RM02", "RM03", "RS01"}
UNMAP_TECH_CODES = {"RM06", "RS02", "RQ02", "RY02"}

TECH_CODE_MAP = {
    "RM05": "煤粉炉", "RM04": "流化床炉",
    "RM01": "自动炉排层燃炉", "RM02": "自动炉排层燃炉",
    "RM03": "自动炉排层燃炉", "RS01": "自动炉排层燃炉",
}
SECTOR_MAP = {"PG": "电力生产", "PS": "电力供应", "HT": "热力生产和供应"}

# A.1 low-NOx combustion NOx removal efficiency (%)
LOW_NOX_NOX_PCT = 22.0

def d1_lookup(sector_name, fuel_key, tech):
    for r in D1:
        if r["sector"] == sector_name and r["fuel"] == fuel_key and r["tech"] == tech:
            return r
    return None

def c_lookup(table, dept, tech, col):
    for r in table:
        if r["dept"] == dept and r["tech"] == tech:
            return r["vals"][col]
    return None

def num(v):
    if v is None or (isinstance(v, float) and math.isnan(v)):
        return None
    return float(v)

# ---------------------------------------------------------------- classification
b102["_is_power_dev"] = b102["电站锅炉/燃气轮机编号"].notna()
b102["_is_ib"] = b102["工业锅炉编号"].notna()
b102["_ind"] = b102["行业类别代码"].astype(str).str.strip()
b102["_port_type"] = np.where(b102["_is_power_dev"], "DZGL", "GYGL")

def classify(row):
    if row["_is_power_dev"]:
        return "POWER", "POWER_DEVICE"
    if row["_is_ib"]:
        if row["_ind"] in D44_POWER:
            return "POWER", "POWER_HEAT_SECTOR"
        return "BOILER", "INDUSTRIAL_BOILER"
    return "OUT_OF_SCOPE", "NO_DEVICE"

decisions = []
for source_id, ridx in idmap.items():
    row = b102.iloc[ridx]
    decided, reason = classify(row)
    decisions.append({"source_id": source_id, "row_index": ridx,
                      "decided_target": decided, "reason_code": reason,
                      "in_scope": decided == "POWER"})

def sector_key(row):
    ind = row["_ind"]
    if ind in ("4411", "4412", "4417"):
        return "PG"
    if ind in ("4419", "4420"):
        return "PS"
    if ind == "4430":
        return "HT"
    # 自备电厂: 电站锅炉 in a non-D44 enterprise -> 电力供应 factors (closest analog)
    return "PS"

# ---------------------------------------------------------------- control facilities
fac_map = {}
for f in b101.itertuples(index=False):
    key = (f[2], f[9])   # 统一社会信用代码, 对应的排放口代码
    fac_map.setdefault(key, []).append({
        "name": f[10], "process": f[15], "eff": f[16]})
CAT_OF_NAME = {"脱硫（酸）设施": "SO2", "脱硝设施": "NOx", "除尘设施": "PM",
               "挥发性有机物治理设施": "VOC"}

def resolve_controls(credit, port_type):
    """returns dict pollutant_cat -> {'present','known','eta','n','reason'}"""
    out = {"SO2": {"present": False, "known": True, "eta": 0.0},
           "NOx": {"present": False, "known": True, "eta": 0.0},
           "PM":  {"present": False, "known": True, "eta": 0.0},
           "VOC": {"present": False, "known": True, "eta": 0.0}}
    facs = fac_map.get((credit, port_type), [])
    for cat in ("SO2", "NOx", "PM", "VOC"):
        flist = [f for f in facs if CAT_OF_NAME.get(f["name"]) == cat]
        if not flist:
            continue
        effs = [f["eff"] for f in flist if isinstance(f["eff"], (int, float)) and not (isinstance(f["eff"], float) and math.isnan(f["eff"])) and 0.0 <= f["eff"] <= 100.0]
        if not effs:
            out[cat] = {"present": True, "known": False, "eta": None, "n": len(flist),
                        "reason": "CONTROL_EFF_UNKNOWN"}
        elif len(set(round(e, 6) for e in effs)) == 1:
            out[cat] = {"present": True, "known": True, "eta": effs[0] / 100.0, "n": len(flist)}
        else:
            out[cat] = {"present": True, "known": False, "eta": None, "n": len(flist),
                        "reason": "CONTROL_EFF_AMBIGUOUS"}
    return out

# ---------------------------------------------------------------- per-source computation
def component_factors(row, comp, sector_name):
    """Resolve factor row + per-pollutant EF availability for one fuel component.
    Returns dict: comp, fuel_name, fuel_key, tech, d1row, activity, unit, status, reason,
    pollutant_factors (dict pollutant->EF or None), component_note"""
    if comp == "FUEL_OTHER":
        val = num(row["其他燃料消耗总量（吨标准煤）"])
        if val is None or val <= 0:
            return None
        return {"comp": comp, "fuel_name": "其他燃料(吨标准煤)", "fuel_key": None,
                "tech": None, "d1row": None, "value": val, "unit": "吨标准煤",
                "status": "insufficient", "reason": "NO_FACTOR_OTHER_FUEL_TCE",
                "ef": {p: None for p in POLLUTANTS}}
    col_type = "燃料一类型" if comp == "FUEL1" else "燃料二类型"
    col_val = "燃料一消耗量" if comp == "FUEL1" else "燃料二消耗量"
    col_unit = "燃料一消耗量单位" if comp == "FUEL1" else "燃料二消耗量单位"
    fuel_name = row[col_type]
    value = num(row[col_val])
    unit = row[col_unit]
    if fuel_name is None or not isinstance(fuel_name, str) or value is None or value <= 0:
        return None
    # device-level no-factor conditions
    dev_type = None
    if row["_is_power_dev"]:
        dev_type = row["电站锅炉/燃气轮机类型"]
    else:
        dev_type = row["工业锅炉类型"]
    if dev_type == "燃气轮机":
        return {"comp": comp, "fuel_name": fuel_name, "fuel_key": None, "tech": "燃气轮机",
                "d1row": None, "value": value, "unit": unit,
                "status": "insufficient", "reason": "GAS_TURBINE_NO_FACTOR",
                "ef": {p: None for p in POLLUTANTS}}
    if fuel_name in NO_FACTOR_FUELS:
        reason = {"生物燃料": "NO_FACTOR_BIOMASS",
                  "城市生活垃圾（用于燃料）": "NO_FACTOR_MSW",
                  "工业废料（用于燃料）": "NO_FACTOR_INDUSTRIAL_WASTE",
                  "其他燃料": "NO_FACTOR_OTHER_FUEL"}[fuel_name]
        return {"comp": comp, "fuel_name": fuel_name, "fuel_key": None, "tech": None,
                "d1row": None, "value": value, "unit": unit,
                "status": "insufficient", "reason": reason,
                "ef": {p: None for p in POLLUTANTS}}
    fuel_key = FUEL_MAP[fuel_name]
    # combustion technology
    if row["_is_power_dev"]:
        tech_code = row["电站锅炉燃烧方式代码"]
    else:
        tech_code = row["工业锅炉燃烧方式代码"]
    if isinstance(tech_code, str):
        tech_code = tech_code.strip()
    if fuel_key in COAL_FAMILY:
        if tech_code in TECH_CODE_MAP:
            tech = TECH_CODE_MAP[tech_code]
        else:
            return {"comp": comp, "fuel_name": fuel_name, "fuel_key": fuel_key,
                    "tech": str(tech_code), "d1row": None, "value": value, "unit": unit,
                    "status": "insufficient", "reason": "SOLID_TECH_UNMAPPABLE",
                    "ef": {p: None for p in POLLUTANTS}}
    elif fuel_key in GAS_M3_FUELS:
        tech = "燃气锅炉"
        if tech_code in SOLID_TECH_CODES:
            return {"comp": comp, "fuel_name": fuel_name, "fuel_key": fuel_key,
                    "tech": tech, "d1row": None, "value": value, "unit": unit,
                    "status": "invalid", "reason": "FUEL_TECH_INCONSISTENT",
                    "ef": {p: None for p in POLLUTANTS}}
    else:
        tech = "燃油锅炉"
        if tech_code in SOLID_TECH_CODES:
            return {"comp": comp, "fuel_name": fuel_name, "fuel_key": fuel_key,
                    "tech": tech, "d1row": None, "value": value, "unit": unit,
                    "status": "invalid", "reason": "FUEL_TECH_INCONSISTENT",
                    "ef": {p: None for p in POLLUTANTS}}
    if fuel_key in ("焦炭", "煤矸石", "其它焦化产品"):
        tech = "不分技术"
    d1row = d1_lookup(sector_name, fuel_key, tech)
    if d1row is None:
        return {"comp": comp, "fuel_name": fuel_name, "fuel_key": fuel_key,
                "tech": tech, "d1row": None, "value": value, "unit": unit,
                "status": "insufficient", "reason": "NO_FACTOR_ROW",
                "ef": {p: None for p in POLLUTANTS}}
    return {"comp": comp, "fuel_name": fuel_name, "fuel_key": fuel_key, "tech": tech,
            "d1row": d1row, "value": value, "unit": unit, "status": "ok", "reason": None,
            "ef": None}

def pollutant_ef(cf, row, sector_name):
    """Return dict pollutant -> EF (float) or None (cannot determine), plus notes."""
    ef = {}
    d1 = cf["d1row"]
    if d1 is None:
        return {p: None for p in POLLUTANTS}, {}
    notes = {}
    def val(key):
        v = d1[key]
        return None if v == "物料衡算" else float(v)
    ef["CO"] = val("CO")
    ef["VOCs"] = val("VOCs")
    # NOx
    nox = d1["NOx"]
    if nox.startswith("装机容量"):
        cap = num(row["对应机组装机容量（万千瓦）"])
        if cap is None:
            ef["NOx"] = None
            notes["NOx"] = "NOX_CAPACITY_MISSING"
        elif cap <= 100:
            ef["NOx"] = 8.96
        elif cap < 300:
            ef["NOx"] = 8.19
        else:
            ef["NOx"] = 7.21
    else:
        ef["NOx"] = float(nox)
    # SO2
    so2 = d1["SO2"]
    if so2 == "物料衡算":
        s = num(row["燃料一平均收到基含硫量"]) if cf["comp"] == "FUEL1" else num(row["燃料二平均收到基含硫量"])
        if s is None:
            ef["SO2"] = None
            notes["SO2"] = "SO2_SULFUR_MISSING"
        else:
            ef["SO2"] = 2.0 * s * (1.0 - 0.15)      # Eq.(3), sr=0.15 (表C.1)
    else:
        ef["SO2"] = float(so2)
    # PM2.5 / PM10 / BC / OC
    pm25 = d1["PM2.5"]
    if pm25 == "物料衡算":
        ash = num(row["燃料一平均收到基灰分（%）"]) if cf["comp"] == "FUEL1" else num(row["燃料二平均收到基灰分（%）"])
        if ash is None:
            for p in ("PM2.5", "PM10", "BC", "OC"):
                ef[p] = None
            notes["PM"] = "PM_ASH_MISSING"
        else:
            ar = c_lookup(C1, sector_name, cf["tech"], 1)
            f25 = c_lookup(C2, sector_name, cf["tech"], 0)
            f10 = c_lookup(C2, sector_name, cf["tech"], 1)
            fb = c_lookup(C3, sector_name, cf["tech"], 0)
            fo = c_lookup(C3, sector_name, cf["tech"], 1)
            pm25_ef = ash * (1.0 - ar) * f25       # Eq.(4)
            pm10_ef = ash * (1.0 - ar) * f10
            ef["PM2.5"] = pm25_ef
            ef["PM10"] = pm10_ef
            if fb is None or fo is None:
                ef["BC"] = None
                ef["OC"] = None
                notes["BC"] = "BC_OC_FACTOR_GAP"
                notes["OC"] = "BC_OC_FACTOR_GAP"
            else:
                ef["BC"] = pm25_ef * fb             # Eq.(5)
                ef["OC"] = pm25_ef * fo             # Eq.(6)
    else:
        for p in ("PM2.5", "PM10", "BC", "OC"):
            ef[p] = float(d1[p])
    return ef, notes

def activity_kg_or_m3(cf):
    """Convert activity to the mass/volume basis of the EF."""
    fuel_key = cf["fuel_key"]
    value = cf["value"]
    if fuel_key in GAS_M3_FUELS:
        if cf["unit"] == "万立方米":
            return value * 1.0e4, "m3", 1.0e6
        return None, cf["unit"], None       # unit mismatch
    if cf["unit"] == "吨":
        return value * 1.0e3, "kg", 1.0e6
    return None, cf["unit"], None

def emission_of(cf, pollutant, eta):
    """generation_t, emission_t for one component-pollutant."""
    a, basis, div = activity_kg_or_m3(cf)
    if a is None:
        return None, None
    e = cf["ef"][pollutant]
    if e is None:
        return None, None
    gen = a * e / div
    emi = gen * (1.0 - (eta if eta is not None else 0.0))
    return gen, emi

# ---------------------------------------------------------------- build items
item_rows = []
exc_sources = {}      # reason -> list of source_ids
counters = {"calculated": 0, "not_involved": 0, "information_insufficient": 0, "source_data_invalid": 0}

for dec in decisions:
    sid = dec["source_id"]
    ridx = dec["row_index"]
    row = b102.iloc[ridx]
    if not dec["in_scope"]:
        for p in POLLUTANTS:
            item_rows.append({
                "source_id": sid, "target": TARGET, "pollutant": p,
                "status": "not_involved", "method": "N/A",
                "activity_record_json": "[]", "parameter_record_json": "[]",
                "control_record_json": "[]",
                "generation_t": "", "emission_t": "",
                "standard_reference": "", "reason_code": "TARGET_OUT_OF_SCOPE"})
        counters["not_involved"] += len(POLLUTANTS)
        continue
    sector_name = SECTOR_MAP[sector_key(row)]
    # no activity at all -> source_data_invalid
    has_any = any(
        (num(row[c]) or 0) > 0 for c in ("燃料一消耗量", "燃料二消耗量", "其他燃料消耗总量（吨标准煤）"))
    if not has_any:
        for p in POLLUTANTS:
            item_rows.append({
                "source_id": sid, "target": TARGET, "pollutant": p,
                "status": "source_data_invalid", "method": "N/A",
                "activity_record_json": "[]", "parameter_record_json": "[]",
                "control_record_json": "[]",
                "generation_t": "", "emission_t": "",
                "standard_reference": "", "reason_code": "NO_ACTIVITY_DATA"})
        counters["source_data_invalid"] += len(POLLUTANTS)
        exc_sources.setdefault("NO_ACTIVITY_DATA", []).append(sid)
        continue
    # components
    comps = []
    c1f = component_factors(row, "FUEL1", sector_name)
    if c1f:
        comps.append(c1f)
    c2f = component_factors(row, "FUEL2", sector_name)
    if c2f:
        comps.append(c2f)
    cf_other = component_factors(row, "FUEL_OTHER", sector_name)
    if cf_other:
        comps.append(cf_other)
    if not comps:
        for p in POLLUTANTS:
            item_rows.append({
                "source_id": sid, "target": TARGET, "pollutant": p,
                "status": "source_data_invalid", "method": "N/A",
                "activity_record_json": "[]", "parameter_record_json": "[]",
                "control_record_json": "[]",
                "generation_t": "", "emission_t": "",
                "standard_reference": "", "reason_code": "NO_ACTIVITY_DATA"})
        counters["source_data_invalid"] += len(POLLUTANTS)
        exc_sources.setdefault("NO_ACTIVITY_DATA", []).append(sid)
        continue
    # resolve EFs per component
    for cf in comps:
        if cf["status"] == "ok":
            ef, notes = pollutant_ef(cf, row, sector_name)
            cf["ef"] = ef
            cf["notes"] = notes
            for p, note in notes.items():
                if note:
                    exc_sources.setdefault(note, []).append(sid)
        else:
            cf["ef"] = {p: None for p in POLLUTANTS}
            cf["notes"] = {}
            if cf["reason"]:
                exc_sources.setdefault(cf["reason"], []).append(sid)
    # controls
    ctrl = resolve_controls(row["统一社会信用代码"], row["_port_type"])
    for cat, info in ctrl.items():
        if info.get("present") and not info.get("known"):
            exc_sources.setdefault(info.get("reason", "CONTROL_EFF_UNKNOWN"), []).append(sid)
    # low-NOx flag (NOx control)
    if row["_is_power_dev"]:
        low_nox = row["是否采用低氮燃烧技术"]
    else:
        low_nox = row["是否采用低氮燃烧技术.1"]
    low_nox_yes = isinstance(low_nox, str) and low_nox.strip() == "是"
    # pollutant eta
    def eta_of(p):
        if p == "SO2":
            return ctrl["SO2"]["eta"]
        if p == "NOx":
            if ctrl["NOx"]["present"]:
                return ctrl["NOx"]["eta"]
            if low_nox_yes:
                return LOW_NOX_NOX_PCT / 100.0
            return 0.0
        if p in ("PM2.5", "PM10", "BC", "OC"):
            return ctrl["PM"]["eta"]
        if p == "VOC":
            return 0.0      # 燃烧烟气VOCs不涉及末端治理 (8.2.1.2-5) -> eta=0
        if p == "CO":
            return 0.0
        return 0.0          # NH3 not applicable
    def control_known(p):
        if p == "SO2":
            return ctrl["SO2"]["known"]
        if p == "NOx":
            return ctrl["NOx"]["known"]
        if p in ("PM2.5", "PM10", "BC", "OC"):
            return ctrl["PM"]["known"]
        return True
    # per pollutant row
    for p in POLLUTANTS:
        if p == "NH3":
            item_rows.append({
                "source_id": sid, "target": TARGET, "pollutant": p,
                "status": "not_involved", "method": "N/A",
                "activity_record_json": json.dumps([], ensure_ascii=False),
                "parameter_record_json": json.dumps([], ensure_ascii=False),
                "control_record_json": json.dumps([], ensure_ascii=False),
                "generation_t": "", "emission_t": "",
                "standard_reference": "T/CSES 144-2024 未提供电力热力源燃烧NH3产生系数",
                "reason_code": "NH3_NO_FACTOR"})
            counters["not_involved"] += 1
            exc_sources.setdefault("NH3_NO_FACTOR", []).append(sid)
            continue
        invalid = any(cf["status"] == "invalid" for cf in comps)
        if invalid:
            status = "source_data_invalid"
            reason = "FUEL_TECH_INCONSISTENT"
            exc_sources.setdefault(reason, []).append(sid)
        else:
            comp_statuses = []
            for cf in comps:
                if cf["status"] == "insufficient":
                    comp_statuses.append("insufficient")
                elif cf["ef"].get(p) is None:
                    comp_statuses.append("insufficient")
                else:
                    comp_statuses.append("ok")
            if not control_known(p):
                comp_statuses = ["insufficient"] * len(comps)
                reason = "CONTROL_EFF_UNKNOWN"
            if all(s == "ok" for s in comp_statuses):
                status = "calculated"
                reason = "CALC_OK"
            else:
                status = "information_insufficient"
                reason = ";".join(sorted(set(cf["reason"] for cf in comps if cf["status"] == "insufficient")) | 
                                    set(cf["notes"].get(p, "") for cf in comps if cf["notes"].get(p)) or 
                                    set(["POLLUTANT_PARAMETER_MISSING"])) if comp_statuses else "POLLUTANT_PARAMETER_MISSING"
                # simplify: pick representative reason
                rs = set()
                for cf in comps:
                    if cf["status"] == "insufficient":
                        rs.add(cf["reason"])
                    if cf["notes"].get(p):
                        rs.add(cf["notes"][p])
                if not control_known(p):
                    rs.add("CONTROL_EFF_UNKNOWN")
                reason = "|".join(sorted(rs)) if rs else "POLLUTANT_PARAMETER_MISSING"
        # build record arrays
        act_rec, par_rec, ctl_rec = [], [], []
        gen_total, emi_total = 0.0, 0.0
        all_calc = True
        for cf in comps:
            comp_id = cf["comp"]
            act_rec.append({"component_id": comp_id, "value": cf["value"], "unit": str(cf["unit"])})
            pars = []
            if cf["fuel_name"] is not None:
                pars.append({"component_id": comp_id, "parameter_id": "fuel_type",
                             "mode": "reported", "value": cf["fuel_name"], "unit": "-"})
            if cf["fuel_key"] is not None:
                pars.append({"component_id": comp_id, "parameter_id": "fuel_key",
                             "mode": "reported", "value": cf["fuel_key"], "unit": "-"})
            if cf["tech"] is not None:
                pars.append({"component_id": comp_id, "parameter_id": "combustion_technology",
                             "mode": "reported", "value": cf["tech"], "unit": "-"})
            # component-level parameters actually used
            if cf["status"] == "ok":
                d1 = cf["d1row"]
                pars.append({"component_id": comp_id, "parameter_id": "ef_source",
                             "mode": "standard_default",
                             "value": "表D.1 %s %s %s" % (sector_name, cf["fuel_key"], cf["tech"]), "unit": "-"})
                for pp in ("CO", "NOx", "SO2", "VOCs", "PM2.5", "PM10", "BC", "OC"):
                    ev = cf["ef"].get(pp)
                    if ev is not None:
                        pars.append({"component_id": comp_id, "parameter_id": "EF_" + pp.replace(".", "_"),
                                     "mode": "standard_default", "value": ev,
                                     "unit": "g/m3" if cf["fuel_key"] in GAS_M3_FUELS else "g/kg"})
                if cf["fuel_key"] in COAL_FAMILY:
                    s = num(row["燃料一平均收到基含硫量"]) if cf["comp"] == "FUEL1" else num(row["燃料二平均收到基含硫量"])
                    ash = num(row["燃料一平均收到基灰分（%）"]) if cf["comp"] == "FUEL1" else num(row["燃料二平均收到基灰分（%）"])
                    if s is not None:
                        pars.append({"component_id": comp_id, "parameter_id": "sulfur_content_received",
                                     "mode": "reported", "value": s, "unit": "%"})
                        pars.append({"component_id": comp_id, "parameter_id": "sr_bottom_ash",
                                     "mode": "standard_default", "value": 0.15, "unit": "-"})
                    if ash is not None:
                        pars.append({"component_id": comp_id, "parameter_id": "ash_content_received",
                                     "mode": "reported", "value": ash, "unit": "%"})
                        ar = c_lookup(C1, sector_name, cf["tech"], 1)
                        f25 = c_lookup(C2, sector_name, cf["tech"], 0)
                        f10 = c_lookup(C2, sector_name, cf["tech"], 1)
                        fb = c_lookup(C3, sector_name, cf["tech"], 0)
                        pars.append({"component_id": comp_id, "parameter_id": "ar_bottom_ash",
                                     "mode": "standard_default", "value": ar, "unit": "-"})
                        pars.append({"component_id": comp_id, "parameter_id": "fpm25",
                                     "mode": "standard_default", "value": f25, "unit": "-"})
                        pars.append({"component_id": comp_id, "parameter_id": "fpm10",
                                     "mode": "standard_default", "value": f10, "unit": "-"})
                        if fb is not None:
                            pars.append({"component_id": comp_id, "parameter_id": "fbc",
                                         "mode": "standard_default", "value": fb, "unit": "-"})
                if d1["NOx"].startswith("装机容量"):
                    cap = num(row["对应机组装机容量（万千瓦）"])
                    if cap is not None:
                        pars.append({"component_id": comp_id, "parameter_id": "unit_capacity",
                                     "mode": "reported", "value": cap, "unit": "万千瓦"})
            if low_nox_yes:
                pars.append({"component_id": comp_id, "parameter_id": "low_nox_combustion",
                             "mode": "reported", "value": "是", "unit": "-"})
            # control record
            if p == "PM10":
                eta = eta_of("PM2.5")
                fine = eta if control_known("PM2.5") else None
                method = "袋式除尘等（报告去除效率）" if ctrl["PM"]["present"] and ctrl["PM"]["known"] else \
                         ("除尘设施（去除效率缺失）" if ctrl["PM"]["present"] else "无除尘治理")
                ctl_rec.append({"component_id": comp_id, "method": method,
                                "efficiency": 0.0,
                                "fine_efficiency": fine if fine is not None else 0.0,
                                "coarse_efficiency": fine if fine is not None else 0.0})
            else:
                eta = eta_of(p)
                ctl_rec.append({"component_id": comp_id,
                                "method": control_method_text(p, ctrl, low_nox_yes),
                                "efficiency": round(eta, 6) if eta is not None else 0.0,
                                "fine_efficiency": 0.0, "coarse_efficiency": 0.0})
            # sums
            if status == "calculated":
                g, e = emission_of(cf, p, eta_of(p))
                if g is None:
                    all_calc = False
                else:
                    gen_total += g
                    emi_total += e
            else:
                all_calc = False
        if status == "calculated":
            counters["calculated"] += 1
            gt = round(gen_total, 9)
            et = round(emi_total, 9)
        else:
            gt, et = "", ""
        item_rows.append({
            "source_id": sid, "target": TARGET, "pollutant": p,
            "status": status,
            "method": method_text(status, p),
            "activity_record_json": json.dumps(act_rec, ensure_ascii=False),
            "parameter_record_json": json.dumps(par_rec, ensure_ascii=False),
            "control_record_json": json.dumps(ctl_rec, ensure_ascii=False),
            "generation_t": gt, "emission_t": et,
            "standard_reference": standard_ref_text(status, p),
            "reason_code": reason})
        if status == "information_insufficient":
            counters["information_insufficient"] += 1
        elif status == "source_data_invalid":
            counters["source_data_invalid"] += 1

def control_method_text(p, ctrl, low_nox_yes):
    if p == "SO2":
        return "脱硫设施（报告去除效率）" if ctrl["SO2"]["present"] else "无脱硫治理"
    if p == "NOx":
        if ctrl["NOx"]["present"]:
            return "脱硝设施（报告去除效率）"
        if low_nox_yes:
            return "低氮燃烧技术（附录A 表A.1 22%）"
        return "无脱硝治理"
    if p in ("PM2.5", "PM10", "BC", "OC"):
        return "除尘设施（报告去除效率）" if ctrl["PM"]["present"] else "无除尘治理"
    if p == "VOC":
        return "燃烧烟气不涉及VOCs末端治理（η=0）"
    return "无治理"

def method_text(status, p):
    if status == "calculated":
        return "产排污系数法（T/CSES 144-2024 公式2）" if p != "SO2" or True else "产排污系数法"
    return "N/A"

def standard_ref_text(status, p):
    if status == "calculated":
        return "T/CSES 144-2024 表D.1、公式(2)"
    return ""

# ---------------------------------------------------------------- write outputs
os.makedirs(OUT, exist_ok=True)
df_dec = pd.DataFrame([{
    "source_id": d["source_id"], "requested_target": TARGET,
    "decided_target": d["decided_target"],
    "disposition": "in_scope" if d["in_scope"] else "out_of_scope",
    "reason_code": d["reason_code"]} for d in decisions])
df_dec.to_csv(OUT + "/source_decisions.csv", index=False, encoding="utf-8-sig")

df_disp = pd.DataFrame([{
    "source_id": d["source_id"], "target": TARGET,
    "disposition": "in_scope" if d["in_scope"] else "out_of_scope",
    "reason_code": d["reason_code"]} for d in decisions])
df_disp.to_csv(OUT + "/generic_source_disposition.csv", index=False, encoding="utf-8-sig")

df_items = pd.DataFrame(item_rows)
df_items.to_csv(OUT + "/generic_inventory_items.csv", index=False, encoding="utf-8-sig")

# exceptions
exc_rows = []
for i, (reason, sids) in enumerate(sorted(exc_sources.items())):
    exc_rows.append({
        "exception_id": "EXC-%03d" % (i + 1),
        "source_id": sorted(sids)[0],
        "pollutant": "ALL" if reason in ("NO_FACTOR_BIOMASS","NO_FACTOR_MSW","NO_FACTOR_INDUSTRIAL_WASTE",
                                         "NO_FACTOR_OTHER_FUEL","NO_FACTOR_OTHER_FUEL_TCE","GAS_TURBINE_NO_FACTOR",
                                         "SOLID_TECH_UNMAPPABLE","FUEL_TECH_INCONSISTENT","NO_ACTIVITY_DATA") else "varies",
        "root_cause": ROOT_CAUSES.get(reason, reason),
        "action_required": ACTIONS.get(reason, "补充数据后重新核算"),
        "affected_count": len(sids)})
pd.DataFrame(exc_rows).to_csv(OUT + "/generic_exception_list.csv", index=False, encoding="utf-8-sig")

summary = {
    "run_id": manifest["run_id"],
    "target": TARGET,
    "input_files": [i["path"] for i in manifest["inputs"]] + [manifest["source_identity_index_path"]],
    "source_count": len(decisions),
    "in_scope_power_count": sum(1 for d in decisions if d["in_scope"]),
