    "item_count": len(item_rows),
    "status_counts": counters,
    "exception_group_count": len(exc_rows),
    "output_paths": {
        "source_decisions": OUT + "/source_decisions.csv",
        "generic_inventory_items": OUT + "/generic_inventory_items.csv",
        "generic_source_disposition": OUT + "/generic_source_disposition.csv",
        "generic_exception_list": OUT + "/generic_exception_list.csv",
        "generic_run_summary": OUT + "/generic_run_summary.json"},
    "unfinished_items": "见 generic_exception_list.csv；主要未决事项：生物质/生活垃圾/工业废料/其他燃料无产生系数、燃气轮机无系数、燃煤燃烧方式无法映射、治理设施去除效率缺失或歧义",
    "rule_scripts": [RUN + "/_work/compute_inventory.py", RUN + "/_work/build_params.py"],
    "method_reference": "T/CSES 144-2024《城市大气污染源排放清单编制技术指南》第7章(电力热力源)、公式(2)-(6)、附录A/C/D",
}
with open(OUT + "/generic_run_summary.json", "w", encoding="utf-8") as f:
    json.dump(summary, f, ensure_ascii=False, indent=1)

print("decisions:", len(df_dec))
print("items:", len(df_items))
