{"content": "# -*- coding: utf-8 -*-
"""
Fixed-combustion POWER (电力热力) inventory computation — generic tool agent run.
Run C-100-POW-GEN-R2. Method: T/CSES 144-2024 城市大气污染源排放清单编制技术指南.
Rules are derived ONLY from the run package inputs (B102-2002, B101-2001, B101-2002,
source_identity_index.json, run_manifest.json) and the provided PDF standard.
"""
import json
import math
import os

RUN = "/Users/wushuo/Desktop/环境学院论文/固定燃烧源清单经验缺失处置实验/实验结果/04_实验C_规模与资源表现/100%规模/02_火电热力/03_通用工具调用型Agent/R2"
INP = RUN + "/inputs"
OUT = RUN + "/outputs"
WORK = RUN + "/_work"

import pandas as pd
import numpy as np

# ---------------------------------------------------------------- inputs
manifest = json.load(open(RUN + "/run_manifest.json", encoding="utf-8"))
TARGET = manifest["target"]                       # POWER
candidate_ids = manifest["candidate_ids"]

idx = json.load(open(INP + "/source_identity_index.json", encoding="utf-8"))
id_records = idx["records"]
assert len(id_records) == len(candidate_ids)
idmap = {}                                        # source_id -> pandas row index
for rec in id_records:
    row_idx = int(rec["source_row"]) - 1          # header is row 1 in the sheet
    idmap[rec["source_id"]] = row_idx
assert set(idmap.keys()) == set(candidate_ids)

b102 = pd.read_excel(INP + "/基102-2002_原始结构脱敏输入.xlsx", sheet_name="Sheet1", header=0)
assert len(b102) == 5922
b101 = pd.read_excel(INP + "/基101-2002_原始结构脱敏输入.xlsx", sheet_name="Sheet1", header=0)

std = json.load(open(WORK + "/standard_parameters.json", encoding="utf-8"))
D1 = std["D1"]; A1 = std["A1"]; C1 = std["C1"]; C2 = std["C2"]; C3 = std["C3"]

# ---------------------------------------------------------------- constants
D44_POWER = {"4411", "4412", "4417", "4419", "4430", "4420"}
POLLUTANTS = ["SO2", "NOx", "CO", "VOC", "PM2.5", "BC", "OC", "NH3", "PM10"]

FUEL_MAP = {
    "原煤": "煤炭", "无烟煤": "煤炭", "一般烟煤": "煤炭", "褐煤": "煤炭",
    "其他洗煤": "煤炭", "煤制品": "煤炭",
    "焦炭": "焦炭", "煤矸石（用于燃料）": "煤矸石", "其他焦化产品": "其它焦化产品",
    "焦炉煤气": "焦炉煤气", "高炉煤气": "高炉煤气", "转炉煤气": "转炉煤气",
    "发生炉煤气": "其它煤气", "天然气": "天然气", "液化天然气": "液化天然气",
    "液化石油气": "液化石油气", "炼厂干气": "炼厂干气", "原油": "原油",
    "柴油": "柴油", "燃料油": "燃料油", "润滑油": "其它液体燃料",
    "其他石油制品": "其它石油制品", "石油焦": "石油焦",
}
NO_FACTOR_REASONS = {
    "生物燃料": "NO_FACTOR_BIOMASS",
    "城市生活垃圾（用于燃料）": "NO_FACTOR_MSW",
    "工业废料（用于燃料）": "NO_FACTOR_INDUSTRIAL_WASTE",
    "其他燃料": "NO_FACTOR_OTHER_FUEL",
}
GAS_M3_FUELS = {"焦炉煤气", "高炉煤气", "其它煤气", "天然气", "转炉煤气", "其它气体燃料"}
COAL_FAMILY = {"煤炭", "焦炭", "煤矸石", "其它焦化产品"}
SOLID_TECH_CODES = {"RM05", "RM04", "RM01", "RM02", "RM03", "RS01"}
UNMAP_TECH_CODES = {"RM06", "RS02", "RQ02", "RY02"}

TECH_CODE_MAP = {
    "RM05": "煤粉炉", "RM04": "流化床炉",
    "RM01": "自动炉排层燃炉", "RM02": "自动炉排层燃炉",
    "RM03": "自动炉排层燃炉", "RS01": "自动炉排层燃炉",
}
SECTOR_MAP = {"PG": "电力生产", "PS": "电力供应", "HT": "热力生产和供应"}

LOW_NOX_NOX_PCT = 22.0

ROOT_CAUSES = {
    "NO_FACTOR_BIOMASS": "生物燃料（生物质）无产生系数：T/CSES 144-2024 表D.1/表E.7未提供生物质锅炉产生系数",
    "NO_FACTOR_MSW": "城市生活垃圾（用于燃料）无产生系数：标准表D.1未提供垃圾焚烧发电系数（废弃物处理源另见附录J，不适用电力热力源）",
    "NO_FACTOR_INDUSTRIAL_WASTE": "工业废料（用于燃料）无产生系数：标准表D.1未覆盖",
    "NO_FACTOR_OTHER_FUEL": "其他燃料无产生系数：标准表D.1未覆盖该燃料类型",
    "NO_FACTOR_OTHER_FUEL_TCE": "其他燃料消耗总量（吨标准煤）无产生系数：标准系数按燃料种类及质量/体积基准给出，无吨标准煤基准系数",
    "GAS_TURBINE_NO_FACTOR": "燃气轮机无产生系数：标准表D.1仅提供燃气锅炉等系数，未提供燃气轮机",
    "SOLID_TECH_UNMAPPABLE": "燃煤锅炉燃烧方式为'其他'或缺失，无法映射到煤粉炉/流化床炉/炉排炉技术",
    "FUEL_TECH_INCONSISTENT": "燃料类型与锅炉燃烧方式不一致（气体/液体燃料配固体燃烧技术），基102行数据矛盾",
    "NO_ACTIVITY_DATA": "基102行无任何燃料消耗量（燃料一/燃料二/其他燃料均为空），且锅炉类型缺失",
    "CONTROL_EFF_UNKNOWN": "匹配到治理设施（基101-2002）但去除效率缺失或同一源多个设施效率不一致，无法确定实际去除效率",
    "CONTROL_EFF_AMBIGUOUS": "同一源匹配到多个同类治理设施且去除效率不一致，无法归一到具体锅炉",
    "SO2_SULFUR_MISSING": "燃煤SO2物料衡算（公式3）需要收到基含硫量，基102未填报",
    "PM_ASH_MISSING": "燃煤PM物料衡算（公式4）需要收到基灰分，基102未填报",
    "BC_OC_FACTOR_GAP": "表C.3未提供该部门/燃烧技术的BC、OC占PM2.5比例（如电力供应-煤粉炉）",
    "NOX_CAPACITY_MISSING": "电力生产燃煤NOx系数按装机容量选取（表D.1注b），基102未填报机组装机容量",
    "NH3_NO_FACTOR": "标准未提供电力热力源燃烧过程的NH3产生系数，NH3不参与火电热力燃烧核算",
}
ACTIONS = {
    "NO_FACTOR_BIOMASS": "补充生物质锅炉产排污系数（如生态环境部公告2021年第24号附表1或实测法）后重新核算",
    "NO_FACTOR_MSW": "确认企业归属（电力热力源/废弃物处理源）并补充相应核算方法后重新核算",
    "NO_FACTOR_INDUSTRIAL_WASTE": "补充工业废料燃烧产排污系数后重新核算",
    "NO_FACTOR_OTHER_FUEL": "明确'其他燃料'具体种类后按相应系数核算",
    "NO_FACTOR_OTHER_FUEL_TCE": "明确其他燃料种类及实物量后按相应系数核算",
    "GAS_TURBINE_NO_FACTOR": "补充燃气轮机产排污系数或实测数据后重新核算",
    "SOLID_TECH_UNMAPPABLE": "核实锅炉实际燃烧方式（煤粉炉/流化床炉/层燃炉）后重新核算",
    "FUEL_TECH_INCONSISTENT": "核实基102填报的燃料与燃烧方式，修正数据后重新核算",
    "NO_ACTIVITY_DATA": "核实该行锅炉是否存在及当年燃料消耗量，补充后重新核算",
    "CONTROL_EFF_UNKNOWN": "补充治理设施实际去除效率或投运率数据后重新核算",
    "CONTROL_EFF_AMBIGUOUS": "核实治理设施与锅炉的对应关系及各自去除效率后重新核算",
    "SO2_SULFUR_MISSING": "补充燃煤收到基含硫量后重新核算",
    "PM_ASH_MISSING": "补充燃煤收到基灰分后重新核算",
    "BC_OC_FACTOR_GAP": "补充该技术BC/OC占PM2.5比例（实测或文献）后重新核算",
    "NOX_CAPACITY_MISSING": "补充机组装机容量后重新核算",
    "NH3_NO_FACTOR": "若需核算NH3，按氨源清单指南（如生态环境部公告2014年第55号附件3）补充SCR/SNCR氨逃逸核算",
}

# ---------------------------------------------------------------- helpers
def num(v):
    if v is None:
        return None
    if isinstance(v, float) and math.isnan(v):
        return None
    return float(v)

def d1_lookup(sector_name, fuel_key, tech):
    for r in D1:
        if r["sector"] == sector_name and r["fuel"] == fuel_key and r["tech"] == tech:
            return r
    return None

def c_lookup(table, dept, tech, col):
    for r in table:
        if r["dept"] == dept and r["tech"] == tech:
            return r["vals"][col]
    return None

def control_method_text(p, ctrl, low_nox_yes):
    if p == "SO2":
        return "脱硫设施（基101-2002报告去除效率）" if ctrl["SO2"]["present"] else "无脱硫治理"
    if p == "NOx":
        if ctrl["NOx"]["present"]:
            return "脱硝设施（基101-2002报告去除效率）"
        if low_nox_yes:
            return "低氮燃烧技术（附录A 表A.1，η=22%）"
        return "无脱硝治理"
    if p in ("PM2.5", "PM10", "BC", "OC"):
        return "除尘设施（基101-2002报告去除效率）" if ctrl["PM"]["present"] else "无除尘治理"
    if p == "VOC":
        return "燃烧烟气VOCs不涉及末端治理（8.2.1.2-5），η=0"
    if p == "CO":
        return "CO无末端治理，η=0"
    return "无治理"

def method_text(status, p):
    if status == "calculated":
        return "产排污系数法（T/CSES 144-2024 公式2）"
    return "N/A"

def standard_ref_text(status, p, cf_list=None, sector_name=None):
    if status == "calculated":
        return "T/CSES 144-2024 表D.1、公式(2)"
    if status == "not_involved" and p == "NH3":
        return "T/CSES 144-2024 未提供电力热力源燃烧NH3产生系数"
    return ""

# ---------------------------------------------------------------- classification
b102["_is_power_dev"] = b102["电站锅炉/燃气轮机编号"].notna()
b102["_is_ib"] = b102["工业锅炉编号"].notna()
b102["_ind"] = b102["行业类别代码"].astype(str).str.strip()
b102["_port_type"] = np.where(b102["_is_power_dev"], "DZGL", "GYGL")

def classify(row):
    if row["_is_power_dev"]:
        return "POWER", "POWER_DEVICE"
    if row["_is_ib"]:
        if row["_ind"] in D44_POWER:
            return "POWER", "POWER_HEAT_SECTOR"
        return "BOILER", "INDUSTRIAL_BOILER"
    return "OUT_OF_SCOPE", "NO_DEVICE"

decisions = []
for source_id, ridx in idmap.items():
    row = b102.iloc[ridx]
    decided, reason = classify(row)
    decisions.append({"source_id": source_id, "row_index": ridx,
                      "decided_target": decided, "reason_code": reason,
                      "in_scope": decided == "POWER"})

def sector_key(row):
    ind = row["_ind"]
    if ind in ("4411", "4412", "4417"):
        return "PG"
    if ind in ("4419", "4420"):
        return "PS"
    if ind == "4430":
        return "HT"
    # 自备电厂: 电站锅炉 in a non-D44 enterprise -> 电力供应 factors (closest analog)
    return "PS"

# ---------------------------------------------------------------- control facilities
fac_map = {}
for f in b101.itertuples(index=False):
    key = (f[2], f[9])   # 统一社会信用代码, 对应的排放口代码
    fac_map.setdefault(key, []).append({"name": f[10], "process": f[15], "eff": f[16]})

CAT_OF_NAME = {"脱硫（酸）设施": "SO2", "脱硝设施": "NOx", "除尘设施": "PM",
               "挥发性有机物治理设施": "VOC"}

def resolve_controls(credit, port_type):
    out = {"SO2": {"present": False, "known": True, "eta": 0.0, "n": 0},
           "NOx": {"present": False, "known": True, "eta": 0.0, "n": 0},
           "PM":  {"present": False, "known": True, "eta": 0.0, "n": 0},
           "VOC": {"present": False, "known": True, "eta": 0.0, "n": 0}}
    facs = fac_map.get((credit, port_type), [])
    for cat in ("SO2", "NOx", "PM", "VOC"):
        flist = [f for f in facs if CAT_OF_NAME.get(f["name"]) == cat]
        if not flist:
            continue
        effs = []
        for f in flist:
            e = f["eff"]
            if isinstance(e, (int, float)) and not (isinstance(e, float) and math.isnan(e)) and 0.0 <= e <= 100.0:
                effs.append(float(e))
        if not effs:
            out[cat] = {"present": True, "known": False, "eta": None, "n": len(flist),
                        "reason": "CONTROL_EFF_UNKNOWN"}
        elif len(set(round(e, 6) for e in effs)) == 1:
            out[cat] = {"present": True, "known": True, "eta": effs[0] / 100.0, "n": len(flist)}
        else:
            out[cat] = {"present": True, "known": False, "eta": None, "n": len(flist),
                        "reason": "CONTROL_EFF_AMBIGUOUS"}
    return out

# ---------------------------------------------------------------- per-component resolution
def component_factors(row, comp, sector_name):
    if comp == "FUEL_OTHER":
        val = num(row["其他燃料消耗总量（吨标准煤）"])
        if val is None or val <= 0:
            return None
        return {"comp": comp, "fuel_name": "其他燃料(吨标准煤)", "fuel_key": None,
                "tech": None, "d1row": None, "value": val, "unit": "吨标准煤",
                "status": "insufficient", "reason": "NO_FACTOR_OTHER_FUEL_TCE",
                "ef": {p: None for p in POLLUTANTS}}
    col_type = "燃料一类型" if comp == "FUEL1" else "燃料二类型"
    col_val = "燃料一消耗量" if comp == "FUEL1" else "燃料二消耗量"
    col_unit = "燃料一消耗量单位" if comp == "FUEL1" else "燃料二消耗量单位"
    fuel_name = row[col_type]
    value = num(row[col_val])
    unit = row[col_unit]
    if fuel_name is None or not isinstance(fuel_name, str) or value is None or value <= 0:
        return None
    if row["_is_power_dev"]:
        dev_type = row["电站锅炉/燃气轮机类型"]
    else:
        dev_type = row["工业锅炉类型"]
    if dev_type == "燃气轮机":
        return {"comp": comp, "fuel_name": fuel_name, "fuel_key": None, "tech": "燃气轮机",
                "d1row": None, "value": value, "unit": unit,
                "status": "insufficient", "reason": "GAS_TURBINE_NO_FACTOR",
                "ef": {p: None for p in POLLUTANTS}}
    if fuel_name in NO_FACTOR_REASONS:
        return {"comp": comp, "fuel_name": fuel_name, "fuel_key": None, "tech": None,
                "d1row": None, "value": value, "unit": unit,
                "status": "insufficient", "reason": NO_FACTOR_REASONS[fuel_name],
                "ef": {p: None for p in POLLUTANTS}}
    fuel_key = FUEL_MAP[fuel_name]
    if row["_is_power_dev"]:
        tech_code = row["电站锅炉燃烧方式代码"]
    else:
        tech_code = row["工业锅炉燃烧方式代码"]
    if isinstance(tech_code, str):
        tech_code = tech_code.strip()
    if fuel_key in COAL_FAMILY:
        if tech_code in TECH_CODE_MAP:
            tech = TECH_CODE_MAP[tech_code]
        else:
            return {"comp": comp, "fuel_name": fuel_name, "fuel_key": fuel_key,
                    "tech": str(tech_code), "d1row": None, "value": value, "unit": unit,
                    "status": "insufficient", "reason": "SOLID_TECH_UNMAPPABLE",
                    "ef": {p: None for p in POLLUTANTS}}
    elif fuel_key in GAS_M3_FUELS:
        tech = "燃气锅炉"
        if tech_code in SOLID_TECH_CODES:
            return {"comp": comp, "fuel_name": fuel_name, "fuel_key": fuel_key,
                    "tech": tech, "d1row": None, "value": value, "unit": unit,
                    "status": "invalid", "reason": "FUEL_TECH_INCONSISTENT",
                    "ef": {p: None for p in POLLUTANTS}}
    else:
        tech = "燃油锅炉"
        if tech_code in SOLID_TECH_CODES:
            return {"comp": comp, "fuel_name": fuel_name, "fuel_key": fuel_key,
                    "tech": tech, "d1row": None, "value": value, "unit": unit,
                    "status": "invalid", "reason": "FUEL_TECH_INCONSISTENT",
                    "ef": {p: None for p in POLLUTANTS}}
    if fuel_key in ("焦炭", "煤矸石", "其它焦化产品"):
        tech = "不分技术"
    d1row = d1_lookup(sector_name, fuel_key, tech)
    if d1row is None:
        return {"comp": comp, "fuel_name": fuel_name, "fuel_key": fuel_key,
                "tech": tech, "d1row": None, "value": value, "unit": unit,
                "status": "insufficient", "reason": "NO_FACTOR_ROW",
                "ef": {p: None for p in POLLUTANTS}}
    return {"comp": comp, "fuel_name": fuel_name, "fuel_key": fuel_key, "tech": tech,
            "d1row": d1row, "value": value, "unit": unit, "status": "ok", "reason": None,
            "ef": None}

def pollutant_ef(cf, row, sector_name):
    ef = {}
    d1 = cf["d1row"]
    if d1 is None:
        return {p: None for p in POLLUTANTS}, {}
    notes = {}
    def val(key):
        v = d1[key]
        return None if v == "物料衡算" else float(v)
    ef["CO"] = val("CO")
    ef["VOCs"] = val("VOCs")
    nox = d1["NOx"]
    if nox.startswith("装机容量"):
        cap = num(row["对应机组装机容量（万千瓦）"])
        if cap is None:
            ef["NOx"] = None
            notes["NOx"] = "NOX_CAPACITY_MISSING"
        elif cap <= 100:
            ef["NOx"] = 8.96
        elif cap < 300:
            ef["NOx"] = 8.19
        else:
            ef["NOx"] = 7.21
    else:
        ef["NOx"] = float(nox)
    so2 = d1["SO2"]
    if so2 == "物料衡算":
        s = num(row["燃料一平均收到基含硫量"]) if cf["comp"] == "FUEL1" else num(row["燃料二平均收到基含硫量"])
        if s is None:
            ef["SO2"] = None
            notes["SO2"] = "SO2_SULFUR_MISSING"
        else:
            ef["SO2"] = 2.0 * s * (1.0 - 0.15)
    else:
        ef["SO2"] = float(so2)
    pm25 = d1["PM2.5"]
    if pm25 == "物料衡算":
        ash = num(row["燃料一平均收到基灰分（%）"]) if cf["comp"] == "FUEL1" else num(row["燃料二平均收到基灰分（%）"])
        if ash is None:
            for p in ("PM2.5", "PM10", "BC", "OC"):
                ef[p] = None
            notes["PM2.5"] = "PM_ASH_MISSING"
        else:
            ar = c_lookup(C1, sector_name, cf["tech"], 1)
            f25 = c_lookup(C2, sector_name, cf["tech"], 0)
            f10 = c_lookup(C2, sector_name, cf["tech"], 1)
            fb = c_lookup(C3, sector_name, cf["tech"], 0)
            fo = c_lookup(C3, sector_name, cf["tech"], 1)
            pm25_ef = ash * (1.0 - ar) * f25
            pm10_ef = ash * (1.0 - ar) * f10
            ef["PM2.5"] = pm25_ef
            ef["PM10"] = pm10_ef
            if fb is None or fo is None:
                ef["BC"] = None
                ef["OC"] = None
                notes["BC"] = "BC_OC_FACTOR_GAP"
                notes["OC"] = "BC_OC_FACTOR_GAP"
            else:
                ef["BC"] = pm25_ef * fb
                ef["OC"] = pm25_ef * fo
    else:
        for p in ("PM2.5", "PM10", "BC", "OC"):
            ef[p] = float(d1[p])
    return ef, notes

def activity_basis(cf):
    fuel_key = cf["fuel_key"]
    value = cf["value"]
    if fuel_key in GAS_M3_FUELS:
        if cf["unit"] == "万立方米":
            return value * 1.0e4, 1.0e6
        return None, None
    if cf["unit"] == "吨":
        return value * 1.0e3, 1.0e6
    return None, None

def emission_of(cf, pollutant, eta):
    a, div = activity_basis(cf)
    if a is None:
        return None, None
    e = cf["ef"].get(pollutant)
    if e is None:
        return None, None
    gen = a * e / div
    emi = gen * (1.0 - (eta if eta is not None else 0.0))
    return gen, emi

